"""Runtime support functions for code generated by archon.transpile.codegen.

Every function here is referenced by name from generated Python source
(as ``rt.<name>(...)``, see codegen.py's RUNTIME_MODULE_ALIAS and
FUNCTION_MAP) -- renaming anything here without updating FUNCTION_MAP in
lockstep will break generated code silently until it's actually run.

Design choice, consistent across the aggregate functions (xl_sum,
xl_average, xl_count, xl_max, xl_min): each accepts *args where every arg
is either a single scalar value or a list of values (a flattened range).
This lets generated code pass SUM(A1, B2:B10, 5) as
``xl_sum(ctx.get(...), ctx.get_range(...), 5)`` without the codegen layer
needing to special-case how many of the arguments happen to be ranges.

Known, deliberate gaps (not oversights) -- these mirror Excel behavior
only approximately, and are flagged rather than silently assumed correct:
  - Excel's SUM/AVERAGE/COUNT/MAX/MIN silently ignore text and blank
    cells inside a range, but raise/behave differently for a text
    argument passed directly (not via a range). This module does NOT
    replicate that direct-vs-range distinction -- it uniformly ignores
    non-numeric values everywhere for the aggregate functions. This is a
    simplification that will diverge from real Excel on edge cases
    involving text literals passed as direct arguments to these
    functions (rare in practice, but a real gap).
  - No date/time serial-number handling exists. Excel represents dates
    as numbers internally; this runtime has no concept of that and will
    not match Excel's date arithmetic.
  - No general floating-point tolerance policy is implemented here --
    per the brief's own section 6, that policy should be decided and
    documented separately (in the parity harness), not silently baked
    into these runtime functions.
  - xl_round uses Python's round(), which uses banker's rounding
    (round-half-to-even) for .5 cases, while Excel's ROUND always rounds
    .5 away from zero. This is a real, known divergence -- e.g.
    round(2.5) == 2 in Python but ROUND(2.5, 0) == 3 in Excel. Fixed
    here using a decimal-based implementation so it matches Excel
    exactly, since getting this wrong directly undermines the parity
    certificate's claim of exactness (see brief section 6's own warning
    about floating-point/rounding mismatches being a real risk).
"""

from __future__ import annotations

import decimal
from collections.abc import Iterable
from typing import Any


def _flatten(args: tuple[Any, ...]) -> list[Any]:
    """Flatten a mix of scalars and lists (from ranges) into one flat list."""
    flat: list[Any] = []
    for arg in args:
        if isinstance(arg, list):
            flat.extend(arg)
        else:
            flat.append(arg)
    return flat


def _numeric_values(values: Iterable[Any]) -> list[float]:
    """Keep only genuinely numeric values (bool excluded -- Excel does not
    treat TRUE/FALSE as 1/0 inside SUM/AVERAGE/etc. ranges), ignoring
    blanks (None) and text, per the aggregate-function gap documented
    in the module docstring."""
    result: list[float] = []
    for v in values:
        if isinstance(v, bool):
            continue
        if isinstance(v, (int, float)):
            result.append(float(v))
    return result


def xl_sum(*args: Any) -> float:
    """Excel SUM: adds all numeric values across scalars and ranges."""
    return sum(_numeric_values(_flatten(args)))


def xl_average(*args: Any) -> float:
    """Excel AVERAGE: mean of all numeric values. Raises ZeroDivisionError
    on no numeric values, mirroring Excel's own #DIV/0! for AVERAGE of
    nothing -- callers in the parity harness should expect and handle
    this the same way a #DIV/0! result would be compared."""
    values = _numeric_values(_flatten(args))
    if not values:
        raise ZeroDivisionError("AVERAGE of no numeric values")
    return sum(values) / len(values)


def xl_count(*args: Any) -> int:
    """Excel COUNT: counts only numeric values (not text, not blanks)."""
    return len(_numeric_values(_flatten(args)))


def xl_max(*args: Any) -> float:
    """Excel MAX: largest numeric value, or 0 if none (Excel's own
    documented behavior for MAX of an empty/non-numeric range)."""
    values = _numeric_values(_flatten(args))
    return max(values) if values else 0.0


def xl_min(*args: Any) -> float:
    """Excel MIN: smallest numeric value, or 0 if none (Excel's own
    documented behavior for MIN of an empty/non-numeric range)."""
    values = _numeric_values(_flatten(args))
    return min(values) if values else 0.0


def xl_if(condition: Any, if_true: Any, if_false: Any = False) -> Any:
    """Excel IF: Python truthiness matches Excel's own TRUE/FALSE-like
    coercion closely enough for the common case (nonzero numbers and
    non-empty strings are truthy), but see the module docstring for
    this runtime's general scope limits."""
    return if_true if condition else if_false


def xl_and(*args: Any) -> bool:
    """Excel AND: true only if every argument is truthy."""
    return all(args)


def xl_or(*args: Any) -> bool:
    """Excel OR: true if any argument is truthy."""
    return any(args)


def xl_not(value: Any) -> bool:
    """Excel NOT: logical negation."""
    return not value


def xl_round(value: float, num_digits: float) -> float:
    """Excel ROUND: rounds half away from zero (e.g. ROUND(2.5, 0) == 3),
    unlike Python's built-in round() which rounds half to even. Uses
    decimal.Decimal with ROUND_HALF_UP to match Excel exactly -- see the
    module docstring for why this precision matters for parity."""
    digits = int(num_digits)
    quantum = decimal.Decimal(1).scaleb(-digits)
    result = decimal.Decimal(str(value)).quantize(
        quantum, rounding=decimal.ROUND_HALF_UP
    )
    return float(result)


def xl_abs(value: float) -> float:
    """Excel ABS: absolute value."""
    return abs(value)


def xl_concatenate(*args: Any) -> str:
    """Excel CONCATENATE: joins all arguments as text, Excel-style (no
    separator, every argument stringified)."""
    return "".join(str(a) for a in args)
